recorder.script:
// DNS probe: the same script runs on the fast path and under the guest's real Node (OXIDEVM_ACCELERATION=off).
// usage: node probe.cjs <section> [...]   sections: lookup lookup-mini timing resolve resolver parallel alive-resolver alive-lookup exit-fast
const dns = require("dns");
const dnsp = dns.promises;
const started = performance.now();
const out = { node: process.version, env: { fast: process.env.OXIDEVM_FAST_DNS_LOOKUP ?? null, acceleration: process.env.OXIDEVM_ACCELERATION ?? null }, sections: process.argv.slice(2), results: {}, timings: {} };
function shape(e) {
  if (!(e instanceof Error)) return { thrown: String(e) };
  const o = { error: e.name, ctor: e.constructor && e.constructor.name, message: e.message, keys: Object.keys(e).sort() };
  for (const k of ["code", "errno", "syscall", "hostname", "address", "port"]) if (k in e) o[k] = e[k];
  return o;
}
const CAP = Number(process.env.PROBE_CAP_MS ?? "90000");
async function t(label, fn) {
  const s = performance.now(); let r;
  let timer;
  try {
    const value = await Promise.race([fn(), new Promise((_, reject) => { timer = setTimeout(() => reject(new Error("probe-cap")), CAP); })]);
    r = { ok: value };
  } catch (e) { r = { err: shape(e) }; }
  clearTimeout(timer);
  r.ms = Math.round((performance.now() - s) * 10) / 10;
  out.results[label] = r;
  if (process.env.PROBE_PROGRESS === "1") process.stderr.write(label + " " + r.ms + "\n");
  return r;
}
const cb = (fn, ...args) => new Promise((resolve, reject) => { fn(...args, (err, ...values) => err ? reject(err) : resolve(values.length === 1 ? values[0] : values)); });
const median = list => { const s = [...list].sort((a, b) => a - b); return s.length === 0 ? null : s[Math.floor(s.length / 2)]; };

const sections = {
  async "lookup"() {
    const names = ["one.test", "multi.test", "dual.test", "v6only.test", "alias.test", "localhost", "oxidevm", "127.0.0.1", "::1", "missing.test", "dangling.test", "servfail.test",
      "big.test", "ONE.TEST", "one.test.", "search", "127.1", "txt.test", "trunc.test", "a..b", "m\u00fcnchen.test", "halffail.test", "refused.test", "mixed.test", "slow.test"];
    const variants = {
      "cb": name => cb(dns.lookup, name),
      "all": name => dnsp.lookup(name, { all: true }),
      "f4": name => dnsp.lookup(name, { family: 4 }),
      "f6": name => dnsp.lookup(name, { family: 6 }),
      "f4all": name => dnsp.lookup(name, { family: 4, all: true }),
      "f6all": name => dnsp.lookup(name, { family: 6, all: true }),
      "v4first": name => dnsp.lookup(name, { all: true, order: "ipv4first" }),
      "v6first": name => dnsp.lookup(name, { all: true, order: "ipv6first" }),
      "addrconfig": name => dnsp.lookup(name, { all: true, hints: dns.ADDRCONFIG }),
      "f6mapped": name => dnsp.lookup(name, { all: true, family: 6, hints: dns.V4MAPPED }),
      "f6mappedall": name => dnsp.lookup(name, { all: true, family: 6, hints: dns.V4MAPPED | dns.ALL }),
    };
    for (const name of names) for (const [variant, fn] of Object.entries(variants)) await t(`lookup ${variant} ${name}`, () => fn(name));
    await t("lookup cb empty", () => cb(dns.lookup, ""));
    await t("lookup default order", async () => dns.getDefaultResultOrder());
  },
